const $=id=>document.getElementById(id);const params=new URLSearchParams(location.search);const layouts=['a','b','c'];const scenarios={problem:{status:'! มีเรื่องที่ควรดู',title:'WhatsApp หลุดมา 6 นาที',description:'เครื่องยังติดต่อได้ · มีงานรอ 3 งาน · คำขอใหม่อาจยังไม่ถึงบอท',action:'ตรวจการเชื่อมต่อ WhatsApp ที่เครื่องบอท',note:'ระบบเห็นการหลุด แต่ยังระบุสาเหตุไม่ได้',time:'13:20:00'},connected:{status:'✓ การเชื่อมต่อพร้อม',title:'ติดต่อบอทได้',description:'เครื่องบอทและ WhatsApp เชื่อมต่ออยู่ · การส่งถึงผู้รับยังไม่ยืนยัน',action:'ยังไม่มีเรื่องที่ต้องจัดการ',note:'ความเงียบในกลุ่มไม่ใช่หลักฐานว่าบอทเสีย',time:'13:20:00'},stale:{status:'? ข้อมูลไม่อัปเดต',title:'ยังยืนยันสถานะตอนนี้ไม่ได้',description:'ไม่ได้รับสถานะใหม่มา 10 นาที · หลักฐานด้านล่างเป็นข้อมูลเก่า',action:'ตรวจว่าเครื่องบอทยังเปิดและเชื่อมต่ออินเทอร์เน็ต',note:'ยังสรุปสาเหตุไม่ได้จากข้อมูลที่มี',time:'13:10:00'},empty:{status:'? ยังไม่มีข้อมูล',title:'ยังรอสถานะแรกจากบอท',description:'เมื่อบอทส่งสถานะเข้ามา จะเห็นหลักฐานและสิ่งที่ควรตรวจที่นี่',action:'รอข้อมูลจากบอท',note:'ยังไม่มีหลักฐานเพียงพอที่จะยืนยันสถานะ',time:null},ai:{status:'! มีเรื่องที่ควรดู',title:'AI สำหรับสรุปบทสนทนามีปัญหา',description:'เครื่องและ WhatsApp เชื่อมต่ออยู่ · งานสรุปล่าสุดไม่สำเร็จ',action:'ตรวจการเชื่อมต่อบริการ AI สำหรับงานสรุป',note:'ความสามารถอื่นอาจยังทำงานได้ตามปกติ',time:'13:20:00'}};const names=['ตอบคำขอ / จัดการงาน','จับงานอัตโนมัติ','สรุปบทสนทนา','อ่านภาพและ PDF','สร้างและแก้ภาพ'];let chosen='connection';
function render(){const key=$('scenario').value,s=scenarios[key],layout=$('composition').value;document.body.dataset.layout=layout;$('status').textContent=s.status;$('headline').textContent=s.title;$('description').textContent=s.description;$('updated').textContent=s.time?'รับสถานะล่าสุด 16 พ.ย. '+s.time:'ยังไม่ได้รับสถานะ';$('guide').hidden=!['problem','stale','ai'].includes(key);$('help-text').textContent=s.note;document.querySelector('#help ol').innerHTML=(key==='ai'?['ตรวจการเชื่อมต่ออินเทอร์เน็ตของเครื่องบอท','ให้ผู้ดูแลตรวจสถานะบริการ AI และรายละเอียดข้อผิดพลาด','รอดูผลเรียกใช้ครั้งต่อไปเพื่อยืนยันการฟื้นตัว']:['ตรวจว่าเครื่องบอทเปิดอยู่และเชื่อมต่ออินเทอร์เน็ต','ตรวจสถานะ WhatsApp และอุปกรณ์ที่ลิงก์บนเครื่อง','หากยังมีปัญหา ให้ผู้ดูแลตรวจบันทึกเหตุการณ์']).map(x=>`<li>${x}</li>`).join('');$('action-list').innerHTML=`<div class="action-row"><span class="rank">01</span><div><strong>${s.action}</strong><p>${s.note}</p></div></div>`;$('model-label').textContent=key==='stale'?'ข้อมูลเก่า · 13:10:00':key==='empty'?'ยังไม่มีข้อมูล':'สถานะล่าสุด';$('model-rows').innerHTML=names.map((n,i)=>`<tr><td>${n}</td><td>${key==='empty'?'ยังไม่ทราบ':'OpenAI'}</td><td>${key==='empty'?'ยังไม่ทราบ':i===4?'example-image-model':'example-text-model'}</td><td>${key==='empty'?'ยังไม่ทราบ':key==='ai'&&i===2?'! ไม่สำเร็จ':key==='stale'?'ผลเก่า: สำเร็จ':'สำเร็จ'}</td><td class="num">${key==='empty'?'—':'13:05:00'}</td></tr>`).join('');const events=[{id:'host',lane:'เครื่องบอท',left:30,label:'12:38:00 · รับสถานะจากเครื่อง',detail:'ได้รับสถานะเครื่อง ณ เวลานี้ ไม่ได้ยืนยันสถานะตลอดช่วง'},{id:'connection',lane:'WhatsApp',left:key==='problem'?90:78.3,label:key==='problem'?'13:14:00 · WhatsApp ขาดการเชื่อมต่อ':'13:07:00 · WhatsApp เชื่อมต่อ',detail:'สถานะจากบอทในเวลานั้น สาเหตุและสถานะอื่นต้องดูหลักฐานเพิ่มเติม'},{id:'sent',lane:'หลักฐานคำตอบ',left:key==='stale'?80:86.7,label:key==='stale'?'13:08:00 · ส่งคำตอบสำเร็จ':'13:12:00 · ส่งคำตอบสำเร็จ',detail:'ส่งสำเร็จยังไม่ยืนยันว่าผู้รับได้รับหรืออ่านแล้ว'}];$('chart').innerHTML=events.map(e=>`<div class="lane"><span class="lane-label">${e.lane}</span><div class="track"><div class="bar unknown"></div>${key==='empty'?'':`<button class="event ${e.id===chosen?'selected':''} ${key==='problem'&&e.id==='connection'?'problem':''}" style="left:${e.left}%" data-id="${e.id}" aria-label="${e.label}" aria-pressed="${e.id===chosen}"></button>`}</div></div>`).join('');let e=events.find(e=>e.id===chosen)||events[1];$('detail').innerHTML=key==='empty'?'<strong>ยังไม่มีเหตุการณ์</strong><p>รอหลักฐานจากบอท</p>':`<strong>${e.label}</strong><p>${e.detail}</p>`;$('chart').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{chosen=b.dataset.id;render();$('chart').querySelector(`[data-id="${chosen}"]`).focus()}));params.set('layout',layout);params.set('scenario',key);history.replaceState(null,'','?'+params)}
$('composition').value=layouts.includes(params.get('layout'))?params.get('layout'):'a';$('scenario').value=scenarios[params.get('scenario')]?params.get('scenario'):'problem';$('composition').addEventListener('change',render);$('scenario').addEventListener('change',()=>{chosen='connection';render()});$('guide').addEventListener('click',()=>$('help').showModal());$('close').addEventListener('click',()=>$('help').close());render();
